insert into public.juniors_questions(slug,subject,chapter_slug,topic,subtopic,prompt,options,correct_option,explanation,difficulty,exam_tags,status,source_reference,validated_at,validated_by,content_version) values
('math-ellipse-standard-01','mathematics','coordinate-geometry','Ellipse','Standard equation','For a>b>0, which is the standard ellipse with major axis along x?','["x²/a²+y²/b²=1","x²/a²−y²/b²=1","y²=4ax","x²+y²=a"]',0,'Both squared terms are positive, and the larger denominator a² sets the major x-axis.','foundation',array['jee-main','tg-eapcet','ap-eapcet'],'published','NCERT Mathematics XI; official JEE Main and EAPCET syllabi',now(),'codex-phase3-review','1.0'),
('math-ellipse-foci-01','mathematics','coordinate-geometry','Ellipse','Eccentricity and foci','For x²/a²+y²/b²=1 with a>b, eccentricity e satisfies:','["e=√(1−b²/a²)","e=√(1+b²/a²)","e=b/a","e=a/b"]',0,'Since c²=a²−b² and e=c/a, e=√(1−b²/a²).','foundation',array['jee-main','tg-eapcet','ap-eapcet'],'published','NCERT Mathematics XI; official JEE Main and EAPCET syllabi',now(),'codex-phase3-review','1.0'),
('math-ellipse-parametric-01','mathematics','coordinate-geometry','Ellipse','Parametric coordinates','A parametric point on x²/a²+y²/b²=1 is:','["(a cosθ,b sinθ)","(a secθ,b tanθ)","(aθ²,2aθ)","(a sinθ,a cosθ)"]',0,'Substitution gives cos²θ+sin²θ=1.','foundation',array['jee-main','tg-eapcet','ap-eapcet'],'published','NCERT Mathematics XI; official JEE Main and EAPCET syllabi',now(),'codex-phase3-review','1.0'),
('math-ellipse-tangent-01','mathematics','coordinate-geometry','Ellipse','Tangent and normal','The tangent to x²/a²+y²/b²=1 at (x₁,y₁) is:','["xx₁/a²+yy₁/b²=1","xx₁/a²−yy₁/b²=1","x+x₁+y+y₁=1","x²x₁²/a²+y²y₁²/b²=1"]',0,'The standard T=0 form replaces each square with the corresponding bilinear term.','foundation',array['jee-main','tg-eapcet','ap-eapcet'],'published','NCERT Mathematics XI; official JEE Main and EAPCET syllabi',now(),'codex-phase3-review','1.0'),
('math-ellipse-auxiliary-circle-01','mathematics','coordinate-geometry','Ellipse','Auxiliary circle','The auxiliary circle of x²/a²+y²/b²=1, a>b, is:','["x²+y²=a²","x²+y²=b²","x²−y²=a²","x²+y²=ab"]',0,'The auxiliary circle is centred at the ellipse centre with radius equal to its semi-major axis a.','foundation',array['jee-main','tg-eapcet','ap-eapcet'],'published','NCERT Mathematics XI; official JEE Main and EAPCET syllabi',now(),'codex-phase3-review','1.0'),
('math-hyperbola-standard-01','mathematics','coordinate-geometry','Hyperbola','Standard and rectangular forms','Which equation is a standard hyperbola opening left and right?','["x²/a²−y²/b²=1","x²/a²+y²/b²=1","y²=4ax","x²+y²=a²"]',0,'The positive x² term sets the transverse axis along x.','foundation',array['jee-main','tg-eapcet','ap-eapcet'],'published','NCERT Mathematics XI; official JEE Main and EAPCET syllabi',now(),'codex-phase3-review','1.0'),
('math-hyperbola-asymptotes-01','mathematics','coordinate-geometry','Hyperbola','Asymptotes','The asymptotes of x²/a²−y²/b²=1 are:','["y=±(b/a)x","y=±(a/b)x","x=±a","y=±b"]',0,'Setting the constant term to zero gives x²/a²−y²/b²=0, hence y=±(b/a)x.','foundation',array['jee-main','tg-eapcet','ap-eapcet'],'published','NCERT Mathematics XI; official JEE Main and EAPCET syllabi',now(),'codex-phase3-review','1.0'),
('math-hyperbola-parametric-01','mathematics','coordinate-geometry','Hyperbola','Parametric coordinates','A parametric point on x²/a²−y²/b²=1 is:','["(a secθ,b tanθ)","(a cosθ,b sinθ)","(aθ²,2aθ)","(a tanθ,b secθ)"]',0,'Substitution uses sec²θ−tan²θ=1.','foundation',array['jee-main','tg-eapcet','ap-eapcet'],'published','NCERT Mathematics XI; official JEE Main and EAPCET syllabi',now(),'codex-phase3-review','1.0'),
('math-hyperbola-tangent-01','mathematics','coordinate-geometry','Hyperbola','Tangent and normal','The tangent to x²/a²−y²/b²=1 at (x₁,y₁) is:','["xx₁/a²−yy₁/b²=1","xx₁/a²+yy₁/b²=1","x+x₁−y−y₁=1","xx₁−yy₁=0"]',0,'The tangent T=0 preserves the minus sign between the bilinear terms.','foundation',array['jee-main','tg-eapcet','ap-eapcet'],'published','NCERT Mathematics XI; official JEE Main and EAPCET syllabi',now(),'codex-phase3-review','1.0'),
('math-hyperbola-director-circle-01','mathematics','coordinate-geometry','Hyperbola','Director circle','The director circle of x²/a²−y²/b²=1 is:','["x²+y²=a²−b²","x²+y²=a²+b²","x²−y²=a²−b²","x²+y²=ab"]',0,'The locus of intersection of perpendicular tangents is x²+y²=a²−b² when this radius is real.','advanced',array['jee-main','tg-eapcet','ap-eapcet'],'published','NCERT Mathematics XI; official JEE Main and EAPCET syllabi',now(),'codex-phase3-review','1.0'),
('math-3d-section-01','mathematics','coordinate-geometry','Three-dimensional geometry','Coordinates and section formula','The midpoint of (1,2,3) and (5,6,7) is:','["(3,4,5)","(2,3,4)","(6,8,10)","(4,4,4)"]',0,'Average corresponding coordinates: ((1+5)/2,(2+6)/2,(3+7)/2)=(3,4,5).','foundation',array['jee-main','tg-eapcet','ap-eapcet'],'published','NCERT Mathematics XII; official JEE Main and EAPCET syllabi',now(),'codex-phase3-review','1.0'),
('math-3d-direction-cosines-01','mathematics','coordinate-geometry','Three-dimensional geometry','Direction ratios and cosines','Direction cosines l,m,n of a line satisfy:','["l²+m²+n²=1","l+m+n=1","lmn=1","l²+m²=n²"]',0,'They are components of a unit direction vector, so the sum of their squares is one.','foundation',array['jee-main','tg-eapcet','ap-eapcet'],'published','NCERT Mathematics XII; official JEE Main and EAPCET syllabi',now(),'codex-phase3-review','1.0'),
('math-3d-lines-01','mathematics','coordinate-geometry','Three-dimensional geometry','Lines in space','A vector equation of the line through position vector a parallel to vector b is:','["r=a+λb","r=λa+b","r=a×b","r·b=a"]',0,'Every point is obtained by moving a scalar multiple of the direction b from point a.','foundation',array['jee-main','tg-eapcet','ap-eapcet'],'published','NCERT Mathematics XII; official JEE Main and EAPCET syllabi',now(),'codex-phase3-review','1.0'),
('math-3d-planes-01','mathematics','coordinate-geometry','Three-dimensional geometry','Planes','A plane with normal vector n through point having position vector a satisfies:','["(r−a)·n=0","(r−a)×n=0","r+a=n","r·a=0"]',0,'Every displacement within the plane is perpendicular to its normal.','foundation',array['jee-main','tg-eapcet','ap-eapcet'],'published','NCERT Mathematics XII; official JEE Main and EAPCET syllabi',now(),'codex-phase3-review','1.0'),
('math-3d-angles-distance-01','mathematics','coordinate-geometry','Three-dimensional geometry','Angles and shortest distance','For skew lines with direction vectors b₁,b₂ and point separation a₂−a₁, their shortest distance is:','["|(a₂−a₁)·(b₁×b₂)|/|b₁×b₂|","|(a₂−a₁)·b₁|/|b₁|","|b₁×b₂|","|(a₂−a₁)×b₁|"]',0,'Project the separation vector onto the unit normal parallel to b₁×b₂.','advanced',array['jee-main','tg-eapcet','ap-eapcet'],'published','NCERT Mathematics XII; official JEE Main and EAPCET syllabi',now(),'codex-phase3-review','1.0')
